/**
 * WhatsApp Web Notification Changer - Main World Injector
 * Hooks native window.Audio and HTMLAudioElement.prototype.play
 */

(function () {
  'use strict';

  // Fallback default audio (WAV Windows Notify Email Base64)
  const DEFAULT_SOUND = "data:audio/wav;base64,";

  // Internal active configuration
  const config = {
    enabled: true,
    audioBase64: DEFAULT_SOUND,
    volume: 0.85,
    matchKeyword: 'static.whatsapp.net',
    soundVersion: 'windows_notify_email_v2'
  };

  // Restore cached configuration synchronously if present
  try {
    const cached = sessionStorage.getItem('__wa_notif_config__');
    if (cached) {
      const parsed = JSON.parse(cached);
      // Ensure cached sound is using the updated Windows Notify Email or user custom audio
      if (parsed && parsed.soundVersion === 'windows_notify_email_v2') {
        if (typeof parsed.enabled === 'boolean') config.enabled = parsed.enabled;
        if (typeof parsed.audioBase64 === 'string' && parsed.audioBase64.length > 20) {
          config.audioBase64 = parsed.audioBase64;
        }
        if (typeof parsed.volume === 'number') config.volume = parsed.volume;
        if (typeof parsed.matchKeyword === 'string') config.matchKeyword = parsed.matchKeyword;
      } else {
        // Invalidate stale cached configuration from older versions
        sessionStorage.removeItem('__wa_notif_config__');
      }
    }
  } catch (err) {
    // SessionStorage access may fail in sandboxed or cross-origin scenarios
  }

  /**
   * Determine if an audio source URL matches WhatsApp notification sounds
   * @param {string} url
   * @returns {boolean}
   */
  function shouldIntercept(url) {
    if (!config.enabled) return false;
    if (!config.audioBase64 || typeof config.audioBase64 !== 'string') return false;
    if (typeof url !== 'string' || !url) return false;
    // Prevent intercepting our own base64 payload
    if (url.startsWith('data:audio') && url.slice(0, 40) === config.audioBase64.slice(0, 40)) {
      return false;
    }
    // Match against user configured keyword (default: static.whatsapp.net)
    if (config.matchKeyword && url.includes(config.matchKeyword)) {
      return true;
    }
    return false;
  }

  // 1. Hook the window.Audio constructor
  const OrigAudio = window.Audio;
  window.Audio = function (...args) {
    const audio = new OrigAudio(...args);
    if (args[0] && shouldIntercept(args[0])) {
      audio.src = config.audioBase64;
      audio.volume = config.volume;
      audio.setAttribute('data-wa-notif-replaced', 'true');
    }
    return audio;
  };
  window.Audio.prototype = OrigAudio.prototype;

  // 2. Hook HTMLAudioElement.prototype.play
  const origPlay = HTMLAudioElement.prototype.play;
  HTMLAudioElement.prototype.play = function () {
    if (this.getAttribute('data-wa-notif-replaced') === 'true') {
      // Audio element was previously replaced. Keep source and volume in sync with active config
      if (config.enabled && config.audioBase64) {
        if (this.src !== config.audioBase64) {
          this.src = config.audioBase64;
        }
        this.volume = config.volume;
      }
    } else if (this.src && shouldIntercept(this.src)) {
      this.src = config.audioBase64;
      this.volume = config.volume;
      this.setAttribute('data-wa-notif-replaced', 'true');
    }
    return origPlay.apply(this, arguments);
  };

  // 3. Hook HTMLMediaElement.prototype.src setter as secondary safety net
  try {
    const srcDescriptor = Object.getOwnPropertyDescriptor(HTMLMediaElement.prototype, 'src');
    if (srcDescriptor && srcDescriptor.set) {
      const origSrcSet = srcDescriptor.set;
      Object.defineProperty(HTMLMediaElement.prototype, 'src', {
        set(val) {
          if (shouldIntercept(val)) {
            origSrcSet.call(this, config.audioBase64);
            this.volume = config.volume;
            this.setAttribute('data-wa-notif-replaced', 'true');
            return;
          }
          origSrcSet.call(this, val);
        },
        get: srcDescriptor.get,
        configurable: true,
        enumerable: true
      });
    }
  } catch (err) {
    // Descriptor hook error fallback
  }

  // 4. Listen for live configuration messages from isolated bridge
  window.addEventListener('message', function (event) {
    if (event.source !== window || !event.data || event.data.type !== 'WA_NOTIF_CONFIG_UPDATE') {
      return;
    }
    const update = event.data.config;
    if (!update) return;

    if (typeof update.enabled === 'boolean') config.enabled = update.enabled;
    if (typeof update.audioBase64 === 'string' && update.audioBase64.length > 20) {
      config.audioBase64 = update.audioBase64;
    }
    if (typeof update.volume === 'number') config.volume = update.volume;
    if (typeof update.matchKeyword === 'string') config.matchKeyword = update.matchKeyword;

    // Cache updated config in sessionStorage for synchronous retrieval on reloads
    try {
      config.soundVersion = 'windows_notify_email_v2';
      sessionStorage.setItem('__wa_notif_config__', JSON.stringify(config));
    } catch (e) {}
  });

})();
